//! The Rust of OrderBook.Money, ported from C# (CodeCoreMorph, D-84).

use std::fmt;
use std::hash::{Hash, Hasher};

use codecoremorph_runtime::{Exception, Result};

/// An amount in one currency, in minor units (cents).
#[derive(Clone, Debug)]
pub struct Money {
    cents: i64,
    currency: String,
}

impl Money {
    pub fn new(cents: i64, currency: &str) -> Money {
        Money {
            cents,
            currency: currency.to_string(),
        }
    }

    pub fn cents(&self) -> i64 {
        self.cents
    }

    pub fn currency(&self) -> &str {
        &self.currency
    }

    pub fn plus(&self, other: &Money) -> Result<Money> {
        if other.currency != self.currency {
            return Err(Exception::invalid_operation(format!(
                "currency mismatch: {} and {}",
                self.currency, other.currency
            )));
        }
        Ok(Money::new(self.cents.wrapping_add(other.cents), &self.currency))
    }

    pub fn times(&self, quantity: i32) -> Money {
        Money::new(self.cents.wrapping_mul(i64::from(quantity)), &self.currency)
    }
}

impl PartialEq for Money {
    fn eq(&self, other: &Money) -> bool {
        self.cents == other.cents && self.currency == other.currency
    }
}

impl Eq for Money {}

impl Hash for Money {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.cents.hash(state);
        self.currency.hash(state);
    }
}

/// `{0}.{1:00} {2}` in the invariant culture, of the cents divided by 100 and their remainder
/// (both truncated toward zero, as C#'s `/` and `%` are).
impl fmt::Display for Money {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let minor = self.cents % 100;
        let sign = if minor < 0 { "-" } else { "" };
        write!(
            f,
            "{}.{}{:02} {}",
            self.cents / 100,
            sign,
            minor.unsigned_abs(),
            self.currency
        )
    }
}

