            CcmInterop.Check(CcmNative.order_book_Money_new(cents, currency, out Handle));
            CcmObjects.Register(Handle.Key, this);
        }

        private Money(order_book_MoneyHandle handle)
        {
            Handle = handle;
        }

        // Book's Snapshot copies the book through a BinaryFormatter until Book is ported: a copy
        // is a new Rust Money of the same amount.
        private Money(SerializationInfo info, StreamingContext context)
            : this(info.GetInt64("cents"), info.GetString("currency"))
        {
        }

        public long Cents
        {
            get
