                long result;
                CcmInterop.Check(CcmNative.order_book_Money_cents(Handle, out result));
                return result;
            }
        }

        public string Currency
        {
            get
            {
                IntPtr result;
                CcmInterop.Check(CcmNative.order_book_Money_currency(Handle, out result));
                return CcmInterop.TakeString(result);
            }
        }

        public Money Plus(Money other)
        {
            order_book_MoneyHandle result;
            CcmInterop.Check(CcmNative.order_book_Money_plus(Handle, HandleOf(other), out result));
            return FromHandle(result);
        }

        public Money Times(int quantity)
        {
            order_book_MoneyHandle result;
            CcmInterop.Check(CcmNative.order_book_Money_times(Handle, quantity, out result));
            return FromHandle(result);
        }

        public override bool Equals(object obj)
        {
            if (!(obj is Money))
            {
                return false;
            }
            Money other = (Money)obj;
            bool result;
            CcmInterop.Check(CcmNative.order_book_Money_equals(Handle, other.Handle, out result));
            return result;
        }

        public override int GetHashCode()
        {
            int result;
            CcmInterop.Check(CcmNative.order_book_Money_hash_code(Handle, out result));
            return result;
        }

        public override string ToString()
        {
            IntPtr result;
            CcmInterop.Check(CcmNative.order_book_Money_to_string(Handle, out result));
            return CcmInterop.TakeString(result);
        }

        void ISerializable.GetObjectData(SerializationInfo info, StreamingContext context)
        {
            info.AddValue("cents", Cents);
            info.AddValue("currency", Currency);
        }

        internal static Money FromHandle(order_book_MoneyHandle handle)
        {
            return CcmObjects.Wrap(handle, h => new Money(h));
        }

        internal static order_book_MoneyHandle HandleOf(Money money)
        {
            return money == null ? order_book_MoneyHandle.Null : money.Handle;
        }
    }
}

