//! The Rust of OrderBook.OrderLine, ported from C# (CodeCoreMorph, D-84).

use std::hash::{Hash, Hasher};
use std::sync::Arc;

use codecoremorph_runtime::{Exception, Result};

use crate::money::Money;

/// One product of an order: so many units at a price.
#[derive(Clone, Debug)]
pub struct OrderLine {
    sku: Option<String>,
    quantity: i32,
    unit_price: Option<Arc<Money>>,
}

impl OrderLine {
    /// A line of `quantity` units of `sku` at `unit_price`. C# let the SKU and the price be
    /// null: they are `None` here.
    pub fn new(
        sku: Option<&str>,
        quantity: i32,
        unit_price: Option<Arc<Money>>,
    ) -> Result<OrderLine> {
        if quantity <= 0 {
            return Err(Exception::argument_out_of_range(
                "quantity",
                "a line has at least one unit",
            ));
        }
        Ok(OrderLine {
            sku: sku.map(str::to_string),
            quantity,
            unit_price,
        })
    }

    pub fn sku(&self) -> Option<&str> {
        self.sku.as_deref()
    }

    pub fn quantity(&self) -> i32 {
        self.quantity
    }

    pub fn unit_price(&self) -> Option<&Arc<Money>> {
        self.unit_price.as_ref()
    }

    /// The unit price, for code that used it: a line without one is C#'s
    /// NullReferenceException.
    pub fn price(&self) -> Result<&Money> {
        self.unit_price.as_deref().ok_or_else(Exception::null_reference)
    }

    pub fn total(&self) -> Result<Money> {
        Ok(self.price()?.times(self.quantity))
    }
}

/// The same SKU, quantity and unit price.
impl PartialEq for OrderLine {
    fn eq(&self, other: &OrderLine) -> bool {
        self.sku == other.sku
            && self.quantity == other.quantity
            && self.unit_price == other.unit_price
    }
}

impl Eq for OrderLine {}

impl Hash for OrderLine {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.sku.hash(state);
        self.quantity.hash(state);
        self.unit_price.hash(state);
    }
}

