//! The Rust of OrderBook.OrderStatus, ported from C# (CodeCoreMorph, D-84).

/// Where an order is between open and shipped. It crosses the bridge as its C# value.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
#[repr(i32)]
pub enum OrderStatus {
    Open = 0,
    Paid = 1,
    Shipped = 2,
    Cancelled = 3,
}

impl OrderStatus {
    /// The status of a C# value, or None for a value no member has (C# lets an enum hold
    /// any int).
    pub fn from_value(value: i32) -> Option<OrderStatus> {
        match value {
            0 => Some(OrderStatus::Open),
            1 => Some(OrderStatus::Paid),
            2 => Some(OrderStatus::Shipped),
            3 => Some(OrderStatus::Cancelled),
            _ => None,
        }
    }

    /// The C# value.
    pub fn value(self) -> i32 {
        self as i32
    }
}

//! The Rust of OrderBook.Order, ported from C# (CodeCoreMorph, D-84).

use std::sync::{Arc, Mutex, MutexGuard};

use codecoremorph_runtime::{Exception, Result};

use crate::money::Money;
use crate::order_line::OrderLine;
use crate::order_status::OrderStatus;

/// An order: its lines, and where it is between open and shipped.
///
/// An order is shared (a book and its callers hold the same one) and changes while shared, so
/// its state is behind its own lock.
#[derive(Debug)]
pub struct Order {
    id: Option<String>,
    state: Mutex<State>,
}

#[derive(Clone, Debug)]
struct State {
    /// C# let a null line be added: None.
    lines: Vec<Option<Arc<OrderLine>>>,
    status: OrderStatus,
    note: Option<String>,
}

fn text_of(status: OrderStatus) -> &'static str {
    match status {
        OrderStatus::Open => "open",
        OrderStatus::Paid => "paid",
        OrderStatus::Shipped => "shipped",
        OrderStatus::Cancelled => "cancelled",
    }
}

/// A line the order holds, which C# dereferenced: a null one is a NullReferenceException.
fn line_of(line: Option<&Arc<OrderLine>>) -> Result<&Arc<OrderLine>> {
    line.ok_or_else(Exception::null_reference)
}

impl Order {
    /// An open order. C# let the ID be null: None, which messages show empty.
    pub fn new(id: Option<&str>) -> Order {
        Order {
            id: id.map(str::to_string),
            state: Mutex::new(State {
                lines: Vec::new(),
                status: OrderStatus::Open,
                note: None,
            }),
        }
    }

    fn state(&self) -> MutexGuard<'_, State> {
        self.state
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
    }

    /// The ID as C# concatenated it into a message: null is empty.
    fn id_text(&self) -> &str {
        self.id.as_deref().unwrap_or("")
    }

    pub fn id(&self) -> Option<&str> {
        self.id.as_deref()
    }

    pub fn status(&self) -> OrderStatus {
        self.state().status
    }

    /// A free-text note; None until someone writes one.
    pub fn note(&self) -> Option<String> {
        self.state().note.clone()
    }

    pub fn set_note(&self, note: Option<&str>) {
        self.state().note = note.map(str::to_string);
    }

    /// The lines, in the order they were added: a copy, which later changes don't reach.
    pub fn lines(&self) -> Vec<Option<Arc<OrderLine>>> {
        self.state().lines.clone()
    }

    pub fn line_count(&self) -> usize {
        self.state().lines.len()
    }

    /// The line at `index`, as the read-only list C# returned gave it: an index past the end
    /// is its ArgumentOutOfRangeException.
    pub fn line_at(&self, index: usize) -> Result<Option<Arc<OrderLine>>> {
        self.state().lines.get(index).cloned().ok_or_else(|| {
            Exception::argument_out_of_range(
                "index",
                "Index was out of range. Must be non-negative and less than the size of the collection.",
            )
        })
    }

    pub fn add(&self, line: Option<Arc<OrderLine>>) -> Result<()> {
        let mut state = self.state();
        if state.status != OrderStatus::Open {
            return Err(Exception::invalid_operation(format!(
                "order {} is {}",
                self.id_text(),
                text_of(state.status)
            )));
        }
        state.lines.push(line);
        Ok(())
    }

    /// The order's total, or None for an order without lines.
    pub fn total(&self) -> Result<Option<Money>> {
        let lines = self.lines();
        let mut lines = lines.iter();
        let Some(first) = lines.next() else {
            return Ok(None);
        };
        let mut total = line_of(first.as_ref())?.total()?;
        for line in lines {
            total = total.plus(&line_of(line.as_ref())?.total()?)?;
        }
        Ok(Some(total))
    }

    /// The first line of the SKU, or None.
    pub fn find(&self, sku: Option<&str>) -> Result<Option<Arc<OrderLine>>> {
        for line in self.lines() {
            let line = line.ok_or_else(Exception::null_reference)?;
            if line.sku() == sku {
                return Ok(Some(line));
            }
        }
        Ok(None)
    }

    pub fn pay(&self) -> Result<()> {
        self.move_to(OrderStatus::Open, OrderStatus::Paid)
    }

    pub fn ship(&self) -> Result<()> {
        self.move_to(OrderStatus::Paid, OrderStatus::Shipped)
    }

    pub fn cancel(&self) -> Result<()> {
        let mut state = self.state();
        if state.status == OrderStatus::Shipped {
            return Err(Exception::invalid_operation(format!(
                "order {} has shipped",
                self.id_text()
            )));
        }
        state.status = OrderStatus::Cancelled;
        Ok(())
    }

    pub fn status_text(&self) -> &'static str {
        text_of(self.status())
    }

    fn move_to(&self, from: OrderStatus, to: OrderStatus) -> Result<()> {
        let mut state = self.state();
        if state.status != from {
            return Err(Exception::invalid_operation(format!(
                "order {} is {}",
                self.id_text(),
                text_of(state.status)
            )));
        }
        state.status = to;
        Ok(())
    }

    /// A copy that later changes to this order don't reach and that shares no object with it:
    /// new lines at new prices, as a serializer's round trip made them.
    pub fn deep_copy(&self) -> Result<Order> {
        let state = self.state().clone();
        let mut lines = Vec::with_capacity(state.lines.len());
        for line in &state.lines {
            lines.push(match line {
                Some(line) => Some(Arc::new(OrderLine::new(
                    line.sku(),
                    line.quantity(),
                    line.unit_price().map(|price| Arc::new((**price).clone())),
                )?)),
                None => None,
            });
        }
        Ok(Order {
            id: self.id.clone(),
            state: Mutex::new(State { lines, ..state }),
        })
    }
}

