using System;
using System.Collections.Generic;
using System.Runtime.Serialization;
using CodeCoreMorph.Interop;

namespace OrderBook
{
    public enum OrderStatus
    {
        Open,
        Paid,
        Shipped,
        Cancelled,
    }

    /// <summary>An order: its lines, and where it is between open and shipped.</summary>
    [Serializable]
    public class Order
    {
        // Not readonly: a copy a BinaryFormatter makes gets its handle in OnDeserialized.
        [NonSerialized]
        internal order_book_OrderHandle Handle;

        // What a BinaryFormatter copy keeps of the order (Book's Snapshot, until Book is
        // ported); set only while one serializes the order. A line's kind is 0 for a null
        // line, 1 for a line without a unit price and 2 for one with a price.
        private string serializedId;
        private OrderStatus serializedStatus;
        private string serializedNote;
        private byte[] serializedKinds;
        private string[] serializedSkus;
        private int[] serializedQuantities;
        private long[] serializedCents;
        private string[] serializedCurrencies;

        public Order(string id)
        {
            CcmInterop.Check(CcmNative.order_book_Order_new(id, out Handle));
            CcmObjects.Register(Handle.Key, this);
        }

        private Order(order_book_OrderHandle handle)
        {
            Handle = handle;
        }

        public string Id
        {
            get
            {
                IntPtr result;
                CcmInterop.Check(CcmNative.order_book_Order_id(Handle, out result));
                return CcmInterop.TakeString(result);
            }
        }

        public OrderStatus Status
        {
            get
            {
                int result;
                CcmInterop.Check(CcmNative.order_book_Order_status(Handle, out result));
                return (OrderStatus)result;
            }
        }

        /// <summary>A free-text note; null until someone writes one.</summary>
        public string Note
        {
            get
            {
                IntPtr result;
                CcmInterop.Check(CcmNative.order_book_Order_note(Handle, out result));
                return CcmInterop.TakeString(result);
            }
            set
            {
                CcmInterop.Check(CcmNative.order_book_Order_set_note(Handle, value));
            }
        }

        public IList<OrderLine> Lines
        {
            get
            {
                int count;
                CcmInterop.Check(CcmNative.order_book_Order_lines_count(Handle, out count));
                List<OrderLine> lines = new List<OrderLine>(count);
                for (int i = 0; i < count; i++)
                {
                    order_book_OrderLineHandle line;
                    CcmInterop.Check(CcmNative.order_book_Order_lines_at(Handle, i, out line));
                    lines.Add(OrderLine.FromHandle(line));
                }
                return lines.AsReadOnly();
            }
        }

        public void Add(OrderLine line)
        {
            CcmInterop.Check(CcmNative.order_book_Order_add(Handle, OrderLine.HandleOf(line)));
        }

        /// <summary>The order's total, or null for an order without lines.</summary>
        public Money Total()
        {
            order_book_MoneyHandle result;
            CcmInterop.Check(CcmNative.order_book_Order_total(Handle, out result));
            return Money.FromHandle(result);
        }

        public OrderLine Find(string sku)
        {
            order_book_OrderLineHandle result;
            CcmInterop.Check(CcmNative.order_book_Order_find(Handle, sku, out result));
            return OrderLine.FromHandle(result);
        }

        public void Pay()
        {
            CcmInterop.Check(CcmNative.order_book_Order_pay(Handle));
        }

        public void Ship()
        {
            CcmInterop.Check(CcmNative.order_book_Order_ship(Handle));
        }

        public void Cancel()
        {
            CcmInterop.Check(CcmNative.order_book_Order_cancel(Handle));
        }

        public string StatusText()
        {
            IntPtr result;
            CcmInterop.Check(CcmNative.order_book_Order_status_text(Handle, out result));
            return CcmInterop.TakeString(result);
        }

        [OnSerializing]
        private void OnSerializing(StreamingContext context)
        {
            serializedId = Id;
            serializedStatus = Status;
            serializedNote = Note;
            IList<OrderLine> lines = Lines;
            serializedKinds = new byte[lines.Count];
            serializedSkus = new string[lines.Count];
            serializedQuantities = new int[lines.Count];
            serializedCents = new long[lines.Count];
            serializedCurrencies = new string[lines.Count];
            for (int i = 0; i < lines.Count; i++)
            {
                OrderLine line = lines[i];
                if (line == null)
                {
                    continue;
                }
                serializedSkus[i] = line.Sku;
                serializedQuantities[i] = line.Quantity;
                Money price = line.UnitPrice;
                serializedKinds[i] = price == null ? (byte)1 : (byte)2;
                if (price != null)
                {
                    serializedCents[i] = price.Cents;
                    serializedCurrencies[i] = price.Currency;
                }
            }
        }

        // The copy is a new Rust order with new lines at new prices: its lines go in while it
        // is open, then the moves that reach its status.
        [OnDeserialized]
        private void OnDeserialized(StreamingContext context)
        {
            CcmInterop.Check(CcmNative.order_book_Order_new(serializedId, out Handle));
            CcmObjects.Register(Handle.Key, this);
            for (int i = 0; i < serializedKinds.Length; i++)
            {
                OrderLine line = null;
                if (serializedKinds[i] != 0)
                {
                    Money price = serializedKinds[i] == 2 ? new Money(serializedCents[i], serializedCurrencies[i]) : null;
                    line = new OrderLine(serializedSkus[i], serializedQuantities[i], price);
                }
                Add(line);
            }
            Note = serializedNote;
            switch (serializedStatus)
            {
                case OrderStatus.Paid:
                    Pay();
                    break;
                case OrderStatus.Shipped:
                    Pay();
                    Ship();
                    break;
                case OrderStatus.Cancelled:
                    Cancel();
                    break;
            }
        }

        internal static Order FromHandle(order_book_OrderHandle handle)
        {
            return CcmObjects.Wrap(handle, h => new Order(h));
        }

        internal static order_book_OrderHandle HandleOf(Order order)
        {
            return order == null ? order_book_OrderHandle.Null : order.Handle;
        }
    }
}

//! The Rust of OrderBook.Book, ported from C# (CodeCoreMorph, D-84).

use std::cmp::Ordering;
use std::collections::HashMap;
use std::sync::{Arc, Mutex, MutexGuard};

use codecoremorph_runtime::{Exception, Result};

use crate::money::Money;
use crate::order::Order;
use crate::order_line::OrderLine;

/// Every order of a shop, by ID.
///
/// A book is shared and changes while shared (orders open in it), so its orders are behind
/// its own lock.
#[derive(Debug, Default)]
pub struct Book {
    orders: Mutex<HashMap<String, Arc<Order>>>,
}

/// `StringComparer.Ordinal`: by UTF-16 code units.
fn ordinal(a: &str, b: &str) -> Ordering {
    a.encode_utf16().cmp(b.encode_utf16())
}

/// A field of an imported row, which C# indexed in an array: a missing one is its
/// IndexOutOfRangeException.
fn field<'a>(fields: &[&'a str], index: usize) -> Result<&'a str> {
    fields
        .get(index)
        .copied()
        .ok_or_else(|| Exception::index_out_of_range("Index was outside the bounds of the array."))
}

fn overflow(type_name: &str) -> Exception {
    Exception::overflow(format!(
        "Value was either too large or too small for an {type_name}."
    ))
}

/// .NET's integer parsing in the invariant culture (`NumberStyles.Integer`): white space
/// around, a sign, then ASCII digits, between `min` and `max`.
fn parse_integer(text: &str, min: i128, max: i128, type_name: &str) -> Result<i128> {
    let trimmed = text.trim_matches(|c: char| matches!(c, '\t'..='\r' | ' '));
    let (negative, digits) = match trimmed.strip_prefix('-') {
        Some(rest) => (true, rest),
        None => (false, trimmed.strip_prefix('+').unwrap_or(trimmed)),
    };
    if digits.is_empty() || !digits.bytes().all(|b| b.is_ascii_digit()) {
        return Err(Exception::format("Input string was not in a correct format."));
    }
    let mut value: i128 = 0;
    for digit in digits.bytes() {
        value = value * 10 + i128::from(digit - b'0');
        if value > i128::from(u64::MAX) {
            return Err(overflow(type_name));
        }
    }
    let value = if negative { -value } else { value };
    if value < min || value > max {
        return Err(overflow(type_name));
    }
    Ok(value)
}

/// `long.Parse(text, CultureInfo.InvariantCulture)`.
fn parse_long(text: &str) -> Result<i64> {
    let value = parse_integer(text, i64::MIN.into(), i64::MAX.into(), "Int64")?;
    i64::try_from(value).map_err(|_| overflow("Int64"))
}

/// `int.Parse(text, CultureInfo.InvariantCulture)`.
fn parse_int(text: &str) -> Result<i32> {
    let value = parse_integer(text, i32::MIN.into(), i32::MAX.into(), "Int32")?;
    i32::try_from(value).map_err(|_| overflow("Int32"))
}

impl Book {
    pub fn new() -> Book {
        Book::default()
    }

    fn orders(&self) -> MutexGuard<'_, HashMap<String, Arc<Order>>> {
        self.orders
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
    }

    pub fn count(&self) -> usize {
        self.orders().len()
    }

    pub fn open(&self, id: &str) -> Result<Arc<Order>> {
        let mut orders = self.orders();
        if orders.contains_key(id) {
            return Err(Exception::argument(format!("order {id} exists"), "id"));
        }
        let order = Arc::new(Order::new(Some(id)));
        orders.insert(id.to_string(), Arc::clone(&order));
        Ok(order)
    }

    /// The order, or None when there is none with that ID.
    pub fn get(&self, id: &str) -> Option<Arc<Order>> {
        self.orders().get(id).cloned()
    }

    /// The orders, by ID in ordinal order.
    fn sorted(&self) -> Vec<(String, Arc<Order>)> {
        let mut orders: Vec<(String, Arc<Order>)> = self
            .orders()
            .iter()
            .map(|(id, order)| (id.clone(), Arc::clone(order)))
            .collect();
        orders.sort_by(|(a, _), (b, _)| ordinal(a, b));
        orders
    }

    /// The IDs, sorted as `StringComparer.Ordinal` sorts them.
    pub fn ids(&self) -> Vec<String> {
        self.sorted().into_iter().map(|(id, _)| id).collect()
    }

    /// A copy of the book that later changes to this one don't reach: each order, line and
    /// price in it is a new one, as the serializer's round trip made them.
    pub fn snapshot(&self) -> Result<Book> {
        let mut orders = HashMap::new();
        for (id, order) in self.sorted() {
            orders.insert(id, Arc::new(order.deep_copy()?));
        }
        Ok(Book {
            orders: Mutex::new(orders),
        })
    }

    /// One line per order line: id,status,sku,quantity,cents,currency.
    pub fn export(&self) -> Result<String> {
        let mut text = String::new();
        for (id, order) in self.sorted() {
            for line in order.lines() {
                // C# dereferenced the line and its unit price.
                let line = line.ok_or_else(Exception::null_reference)?;
                let price = line.price()?;
                text.push_str(&format!(
                    "{id},{},{},{},{},{}\n",
                    order.status_text(),
                    line.sku().unwrap_or(""),
                    line.quantity(),
                    price.cents(),
                    price.currency()
                ));
            }
        }
        Ok(text)
    }

    /// The open orders of an [`Book::export`].
    pub fn import(text: &str) -> Result<Book> {
        let book = Book::new();
        // StringReader.ReadLine ends a line at \n, \r or \r\n: the empty rows between are
        // skipped, as empty lines are.
        for row in text.split(['\r', '\n']) {
            if row.is_empty() {
                continue;
            }
            let fields: Vec<&str> = row.split(',').collect();
            let id = field(&fields, 0)?;
            let order = match book.get(id) {
                Some(order) => order,
                None => book.open(id)?,
            };
            let price = Money::new(parse_long(field(&fields, 4)?)?, field(&fields, 5)?);
            let sku = field(&fields, 2)?;
            let quantity = parse_int(field(&fields, 3)?)?;
            let line = OrderLine::new(Some(sku), quantity, Some(Arc::new(price)))?;
            order.add(Some(Arc::new(line)))?;
        }
        Ok(book)
    }
}

