//! The Rust of OrderBook.Report, ported from C# (CodeCoreMorph, D-84).

use codecoremorph_runtime::{Exception, Result};

use crate::book::Book;
use crate::money::Money;
use crate::order::Order;
use crate::order_status::OrderStatus;

/// The table's headings (C#'s static Headings).
const HEADINGS: [&str; 3] = ["id", "status", "total"];

/// What [`describe`] tells apart of the value C# passed as an object.
#[derive(Clone, Copy, Debug)]
pub enum Value<'a> {
    Text(&'a str),
    Order(&'a Order),
    Money(&'a Money),
    /// Anything else, null included.
    Other,
}

pub fn describe(value: Value<'_>) -> String {
    match value {
        Value::Text(text) => format!("text: {text}"),
        Value::Order(order) => format!(
            "order {} ({})",
            order.id().unwrap_or(""),
            order.status_text()
        ),
        Value::Money(money) => format!("amount {money}"),
        Value::Other => "unknown".to_string(),
    }
}

pub fn is_final(status: OrderStatus) -> bool {
    matches!(status, OrderStatus::Shipped | OrderStatus::Cancelled)
}

/// A row per order, by ID: its ID, status and total (`-` for none), after the headings.
pub fn table(book: &Book) -> Result<String> {
    let mut text = HEADINGS.join("\t");
    text.push('\n');
    for id in book.ids() {
        let order = book.get(&id).ok_or_else(Exception::null_reference)?;
        let total = order.total()?;
        text.push_str(&id);
        text.push('\t');
        text.push_str(order.status_text());
        text.push('\t');
        match total {
            Some(total) => text.push_str(&total.to_string()),
            None => text.push('-'),
        }
        text.push('\n');
    }
    Ok(text)
}

/// The SKU of each line, in order; C# let a SKU be null (None), and dereferenced each line,
/// so a null one is a NullReferenceException.
pub fn skus(order: &Order) -> Result<Vec<Option<String>>> {
    order
        .lines()
        .into_iter()
        .map(|line| {
            let line = line.ok_or_else(Exception::null_reference)?;
            Ok(line.sku().map(str::to_string))
        })
        .collect()
}

